import { containerPrefill } from "./leaf-prefill-containers.js";
import { eventV7Prefill, predicateConditionPrefill } from "./leaf-prefill-conditions.js";

/** A family parameter's JSON Schema, as far as the leaf form and the prefill read it. */
export type Property = {
  enum?: string[]; anyOf?: Property[]; type?: string; pattern?: string; minimum?: number; maximum?: number;
  items?: { enum?: string[]; type?: string; pattern?: string };
  minItems?: number;
  "x-only-when"?: Record<string, readonly string[]>;
};
/** The part of a reviewed family the prefill needs; registry entries and the bridge's listing both fit. */
export type PrefillFamily = { id: string; parameterSchema: { properties?: Record<string, Property> } };

/**
 * What the source wording states outright about a leaf's parameters. Nothing is chosen by
 * default: a parameter is filled in only when the words say it (a bracketed weapon ability,
 * melee or ranged, an "N+" threshold, an event's phase, a unit keyword in capitals, "not").
 */

export function choices(property: Property): string[] {
  return property.enum ?? property.anyOf?.flatMap((item) => item.enum ?? []) ?? [];
}
const numeric = (property: Property) => property.type === "integer" || (property.anyOf?.some((item) => item.type === "integer") ?? false);
const freeText = (property: Property) => property.anyOf?.some((item) => item.type === "string") ?? property.type === "string";

const titleCase = (text: string) => text.toLowerCase().replace(/(^|[\s-])(\p{L})/gu, (_match, lead: string, letter: string) => lead + letter.toUpperCase());

/** The weapon ability named in brackets in the source, spelled the way the DSL spells it. */
function keywordFromSource(exactText: string, options: readonly string[]): string | null {
  const bracketed = /\[([^\]]+)\]/u.exec(exactText)?.[1];
  if (!bracketed) return null;
  const named = options.find((option) => option.toLowerCase() === bracketed.trim().toLowerCase());
  if (named) return named;
  const valued = /^(sustained hits|rapid fire|melta) (\d|d3|d6)$/iu.exec(bracketed.trim());
  return valued ? `${titleCase(valued[1]!)} ${valued[2]!.toUpperCase()}` : null;
}

/** An event's kind, phase, and whose turn. */
function eventFromSource(exactText: string): Record<string, unknown> {
  const boundary = /\b(start|end) of (your opponent's|your|the|each|either player's) (command|movement|shooting|charge|fight) phase\b/iu.exec(exactText);
  if (boundary) {
    const owner = boundary[2]!.toLowerCase();
    return {
      kind: boundary[1]!.toLowerCase() === "start" ? "phase-start" : "phase-end",
      phase: boundary[3]!.toLowerCase(),
      turn: owner === "your" ? "your" : owner === "your opponent's" ? "opponent" : "either",
    };
  }
  if (/\bafter this unit has shot\b/iu.test(exactText)) return { kind: "after-shooting" };
  if (/\ba model in this unit is destroyed\b/iu.test(exactText)) return { kind: "model-destroyed" };
  if (/\b(?:this model|the bearer) is destroyed\b/iu.test(exactText)) return { kind: "this-model-destroyed" };
  const moments: Array<[RegExp, string]> = [
    [/enemy unit has selected its targets/iu, "enemy-selected-targets"], [/enemy unit ends an? (?:normal|advance|fall back|[a-z, ]+) move/iu, "enemy-ended-move"],
    [/enemy unit has shot/iu, "enemy-has-shot"], [/enemy unit declares a charge/iu, "enemy-declared-charge"],
    [/is selected to shoot/iu, "selected-to-shoot"], [/is selected to fight/iu, "selected-to-fight"],
  ];
  const moment = moments.find(([pattern]) => pattern.test(exactText))?.[1];
  if (moment) return { kind: moment };
  return {};
}

/**
 * Rules text prints curly apostrophes ("bearer’s", "can’t", "opponent’s"); the patterns here are
 * written with straight ones. Nothing the prefill returns quotes the source, so reading the
 * text with straight apostrophes changes no value's spelling.
 */
const straightApostrophes = (text: string) => text.replace(/[\u2018\u2019\u02BC]/gu, "'");

/**
 * An effect's subject when the words name the bearer. The bearer is the model that has the
 * ability; the bearer's unit is its unit.
 */
/** "This model", not "this model's unit" (bearerSubject reads that as the unit). */
const THIS_MODEL = /\bthis model\b(?!['’]s unit\b)/iu;

function bearerSubject(text: string): "this-unit" | "this-model" | null {
  // The bearer's (or this model's) unit is the unit, with either apostrophe.
  if (/\b(?:the bearer|this model)['’]s unit\b/iu.test(text)) return "this-unit";
  return /\bthe bearer\b/iu.test(text) ? "this-model" : null;
}

/** Who attacks, which way, and with what, when the words say so. */
function attackFromSource(text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const lower = text.toLowerCase();
  if (/\battacks? (?:targets?|is allocated to)\b/u.test(lower)) result.direction = "targeted";
  else if (/\bmakes? an? (?:melee |ranged )?attack/u.test(lower)) result.direction = "makes";
  const type = /\b(melee|ranged)\b/u.exec(lower)?.[1];
  if (type) result.attack_type = type;
  else if (/\battack/u.test(lower)) result.attack_type = "any";
  const units: Array<[RegExp, string]> = [
    [/\ba model in the bearer's unit\b|\bthe bearer's unit\b/u, "bearers-unit"],
    [/\bthe bearer\b/u, "this-model"],
    [/\ba model in this unit\b|\bthis unit\b/u, "this-unit"],
    [/\bthis model\b/u, "this-model"],
    [/\ba model in (?:that|your) unit\b|\b(?:that|your) unit\b/u, "that-unit"],
  ];
  const unit = units.find(([pattern]) => pattern.test(lower))?.[1];
  if (unit) result.unit = unit;
  return result;
}

/** Unit keywords written in capitals or bold, and "can fly" as FLY. */
function unitKeywords(text: string): string[] {
  const found = new Set<string>();
  for (const match of text.matchAll(/\*\*([^*]+)\*\*|\b([A-Z][A-Z-]{2,}(?: [A-Z][A-Z-]{2,})*)\b/gu)) {
    const keyword = (match[1] ?? match[2] ?? "").trim().toUpperCase();
    if (keyword) found.add(keyword);
  }
  if (/\b(?:can|cannot|can't) fly\b/iu.test(text)) found.add("FLY");
  return [...found];
}

const STATE_WORDS: Array<[RegExp, string]> = [
  [/starting strength/iu, "below-starting-strength"], [/half[- ‑]?strength/iu, "below-half-strength"], [/battle[- ]?shocked/iu, "battle-shocked"],
  [/engagement range|\bengaged\b|\bunengaged\b/iu, "engaged"],
  [/on the battlefield/iu, "on-battlefield"], [/\bhidden\b/iu, "hidden"],
];
const MARK_WORDS: Array<[RegExp, string]> = [
  [/oath of moment/iu, "oath-of-moment"], [/afflicted/iu, "afflicted"], [/spotted/iu, "spotted"], [/marked/iu, "marked"],
];

function predicateFromSource(familyId: string, text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  if (/\btargets?\b|\bthe target\b/iu.test(text)) result.subject = "target";
  else if (/\bthis unit\b/iu.test(text)) result.subject = "this-unit";
  else if (familyId === "unit-state" && /\b(?:this model|the bearer)\b/iu.test(text)) result.subject = "this-model";
  if (/\bnot\b|\bcannot\b|\bcan't\b/iu.test(text)) result.negated = true;
  const inches = /(\d+)(?:"|”|″| inches)/u.exec(text)?.[1];
  if (familyId === "unit-state") {
    const states = STATE_WORDS.filter(([pattern]) => pattern.test(text)).map(([, state]) => state);
    if (states.length) result.states = states;
  } else if (familyId === "unit-keyword") {
    const keywords = unitKeywords(text);
    if (keywords.length) result.keywords = keywords;
  } else if (familyId === "unit-mark") {
    const mark = MARK_WORDS.find(([pattern]) => pattern.test(text))?.[1];
    if (mark) result.mark = mark;
  } else if (familyId === "unit-position") {
    if (/closest eligible/iu.test(text)) result.kind = "closest-eligible";
    else if (/objective/iu.test(text)) result.kind = "objective-range";
    else if (/more than \d/iu.test(text)) result.kind = "beyond";
    else if (/within \d/iu.test(text)) result.kind = "within";
    if (inches && (result.kind === "within" || result.kind === "beyond")) result.inches = Number(inches);
    // What the distance is measured from, when the words say it plainly: "of this model", "of this
    // unit", or a bare "12\" away" (away from this unit). "Of that enemy unit" is left to review.
    if (result.kind === "within" || result.kind === "beyond") {
      if (/\bof this model\b/iu.test(text)) result.of = "this-model";
      else if (/\bof (?:this|your) unit\b/iu.test(text) || (/\baway\b/iu.test(text) && !/\bof\b/iu.test(text))) result.of = "this-unit";
    }
    if (result.kind === "objective-range") result.controlled_by = /you control/iu.test(text) ? "you" : /opponent controls/iu.test(text) ? "opponent" : "any";
  }
  return result;
}

function selectionFromSource(text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  if (/\benemy\b/iu.test(text)) result.scope = "enemy";
  else if (/\bfriendly\b/iu.test(text)) result.scope = "friendly";
  const inches = /within (\d+)(?:"|”|″| inches)/iu.exec(text)?.[1];
  if (inches) {
    result.distance = "within";
    result.inches = Number(inches);
  }
  if (/\bvisible\b/iu.test(text)) result.visible = true;
  return result;
}

/** Characteristic names as GW writes them, longest first so "weapon skill" wins over "skill". */
const CHARACTERISTIC_WORDS: Array<[RegExp, string]> = [
  [/armou?r penetration/iu, "AP"], [/ballistic skill/iu, "BS"], [/weapon skill/iu, "WS"], [/objective control/iu, "OC"],
  [/\battacks\b/iu, "A"], [/\bstrength\b/iu, "S"], [/\bdamage\b/iu, "D"], [/\bmove\b/iu, "M"], [/\btoughness\b/iu, "T"],
  [/\bsave\b/iu, "Sv"], [/\bwounds\b/iu, "W"], [/\bleadership\b/iu, "Ld"],
];
const CHARACTERISTIC_ORDER = ["M", "T", "Sv", "W", "Ld", "OC", "A", "WS", "BS", "S", "AP", "D"];

function characteristicFromSource(text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const shorthand = /^([+\-−‐‑‒–—])\s*(\d+)\s*(OC|Ld|AP|WS|BS|Sv|M|T|W|A|S|D)[.!]?$/iu.exec(text.replaceAll("*", "").trim());
  if (shorthand) return {
    characteristics: [CHARACTERISTIC_ORDER.find((stat) => stat.toLowerCase() === shorthand[3]!.toLowerCase())!],
    operation: shorthand[1] === "+" ? "improve" : "worsen",
    value: Number(shorthand[2]),
  };
  const found = CHARACTERISTIC_WORDS.filter(([pattern]) => pattern.test(text)).map(([, stat]) => stat);
  if (found.length) result.characteristics = CHARACTERISTIC_ORDER.filter((stat) => found.includes(stat));
  const verb = /\b(add|subtract|improve|worsen)\b/iu.exec(text)?.[1]?.toLowerCase();
  if (verb) result.operation = verb;
  const amount = /\bby (\d+)\b|\b(?:add|subtract) (\d+)\b/iu.exec(text);
  if (amount) result.value = Number(amount[1] ?? amount[2]);
  const weapons = /\b(melee|ranged) weapons\b/iu.exec(text)?.[1]?.toLowerCase();
  if (weapons) result.weapon_type = weapons;
  else if (/\bweapons\b/iu.test(text)) result.weapon_type = "all";
  if (/\b(?:that|this|the) attack\b/iu.test(text)) {
    result.subject = "attack";
    result.weapon_type = "all";
  } else if (/\bthis model\b/iu.test(text)) result.subject = "this-model";
  else if (bearerSubject(text)) result.subject = bearerSubject(text);
  else if (/\b(?:that|this|your) unit\b/iu.test(text)) result.subject = "this-unit";
  return result;
}

const WINDOW_PHASES = ["command", "movement", "shooting", "charge", "fight"];

/** "Your opponent's Shooting phase or the Fight phase": each phase with its own owner. */
function windowFromSource(text: string): Record<string, unknown> {
  const window: Record<string, string[]> = { your_phases: [], opponent_phases: [], either_phases: [] };
  const lower = text.toLowerCase();
  if (/\bany phase\b/u.test(lower)) return { ...window, either_phases: [...WINDOW_PHASES] };
  let previous = "either_phases";
  for (const part of lower.split(/\bor\b|,/u)) {
    const phase = WINDOW_PHASES.find((item) => part.includes(item));
    if (!phase) continue;
    // "Your Movement or Charge phase": a phase without its own owner shares the one before it;
    // "the Fight phase" and a bare "Fight phase" belong to either player's turn.
    const owner = /your opponent's/u.test(part) ? "opponent_phases" : /\byour\b/u.test(part) ? "your_phases"
      : /\bthe\b/u.test(part) || part.trim().startsWith(phase) && previous === "either_phases" ? "either_phases" : previous;
    if (!window[owner]!.includes(phase)) window[owner]!.push(phase);
    previous = owner;
  }
  return window;
}

/** Keywords in capitals or bold, split on commas and "or"; "or" means any one of them. */
function targetKeywords(text: string): { keywords: string[]; match: string } {
  const plain = text.replaceAll("*", "");
  const found = [...plain.matchAll(/\b[A-Z][A-Z'-]+(?: [A-Z][A-Z'-]+)*\b/gu)].map((match) => match[0].trim()).filter((word) => word.length > 1);
  return { keywords: [...new Set(found)], match: /\bor\b/u.test(plain) && found.length > 1 ? "any" : "all" };
}

function targetFromSource(familyId: string, text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const excludedPart = /\(excluding ([^)]+)\)/iu.exec(text)?.[1] ?? "";
  const main = text.replace(/\(excluding [^)]+\)/iu, "").replace(/\bthat (?:has|was|had|is|disembarked)\b.*$/iu, "");
  const { keywords, match } = targetKeywords(main);
  result.keywords = keywords;
  result.match = match;
  result.selects = /\bmodel\b/iu.test(main) && !/\bunit\b/iu.test(main) ? "model" : "unit";
  if (familyId === "stratagem-target") {
    result.excluded_keywords = targetKeywords(excludedPart).keywords;
    const upTo = /\bup to (two|three|four|\d+)\b/iu.exec(main)?.[1]?.toLowerCase();
    if (upTo) {
      result.count = "up-to";
      result.count_max = ({ two: 2, three: 3, four: 4 } as Record<string, number>)[upTo] ?? Number(upTo);
    } else result.count = /\bone or more\b/iu.test(main) ? "one-or-more" : "one";
    result.side = /\benemy\b/iu.test(main) ? "enemy" : "your-army";
  }
  return result;
}

const PREDICATES = new Set(["unit-state", "unit-keyword", "unit-mark", "unit-position"]);
/** Batch 6's new predicate families, prefilled by `leaf-prefill-conditions.ts`. */
const NEW_PREDICATES = new Set([
  "rule-active", "unit-owner", "unit-has-ability", "same-unit", "model-count", "wounds-state", "in-region",
  "controls-objective", "visible", "designated-filter", "battle-round", "battle-size", "guided", "moved-over",
  "phase-window", "attack-filter", "attack-compare", "history-compare",
]);

export function prefillFromSource(family: PrefillFamily | undefined, sourceText: string): Record<string, unknown> {
  if (!family) return {};
  const exactText = straightApostrophes(sourceText);
  const eventPrefill = () => {
    const v1to6 = eventFromSource(exactText);
    return Object.keys(v1to6).length ? v1to6 : eventV7Prefill(exactText);
  };
  const prefill: Record<string, unknown> = family.id === "event" ? eventPrefill()
    : family.id === "attack" ? attackFromSource(exactText)
      : family.id === "select-unit" ? selectionFromSource(exactText)
        : PREDICATES.has(family.id) ? predicateFromSource(family.id, exactText)
          : NEW_PREDICATES.has(family.id) ? predicateConditionPrefill(family.id, exactText) : containerPrefill(family.id, exactText);
  if (family.id === "characteristic-modifier") Object.assign(prefill, characteristicFromSource(exactText));
  if (family.id === "weapon-property-scope") {
    const frame = /^(this unit|this model|that unit)'s (?:(melee|ranged) )?attacks have(?: the)?$/iu.exec(exactText.replace(/\*/gu, "").trim());
    if (frame) {
      prefill.subject = frame[1]!.toLowerCase() === "that unit" ? "selected-unit" : frame[1]!.toLowerCase().replace(" ", "-");
      prefill.weapon_type = frame[2]?.toLowerCase() ?? "all";
    }
  }
  if (family.id === "no-advance-roll") {
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
    else if (/\b(?:it|your unit|this unit|that unit)\b/iu.test(exactText)) prefill.subject = "this-unit";
  }
  if (family.id === "roll-prohibition" && /\bdeadly demise\b/iu.test(exactText)) prefill.roll = "deadly-demise";
  if (family.id === "dice-roll") {
    const dice = /\broll (?:one |a )?(d3|d6|2d6)\b/iu.exec(exactText)?.[1]?.toUpperCase();
    if (dice) prefill.dice = dice;
  }
  if (family.id === "roll-result") {
    const band = /\bon an? (\d+)(?:\+|-(\d+))?/iu.exec(exactText);
    if (band) {
      prefill.from = Number(band[1]);
      if (band[2]) prefill.to = Number(band[2]);
      else if (!band[0].endsWith("+")) prefill.to = Number(band[1]);
    }
  }
  if (family.id === "mortal-wounds") {
    const count = /\b(\d+|d3\+3|d3|d6|2d6) mortal wounds?\b/iu.exec(exactText)?.[1]?.toUpperCase();
    if (count) prefill.count = count;
    if (/\bthat (?:enemy )?unit\b/iu.test(exactText)) prefill.recipient = "that-unit";
    else if (/\bthis unit\b/iu.test(exactText)) prefill.recipient = "this-unit";
    else if (/\bthis model\b/iu.test(exactText)) prefill.recipient = "this-model";
  }
  if (family.id === "fight-on-death") {
    if (/after the attacking unit has finished/iu.test(exactText)) prefill.timing = "after-the-attacking-unit-finishes";
    else if (/when (?:its|that) unit (?:is selected to )?fights?/iu.test(exactText)) prefill.timing = "when-its-unit-fights";
    if (/\bcan shoot\b/iu.test(exactText)) {
      prefill.act = "shoot";
      if (/\bthis unit\b/iu.test(exactText)) prefill.subject = "this-unit";
      else if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    } else if (/\bcan fight\b/iu.test(exactText) || prefill.timing) prefill.act = "fight";
  }
  if (family.id === "reroll") {
    // "re-roll one Hit roll" names how many; higher counts are spelled out or left for review.
    if (/\bre-roll (?:one|a single)\b/iu.test(exactText)) prefill.count = 1;
  }
  if (family.id === "ignore-modifiers") {
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
    else if (/\b(?:this|that|your) unit\b/iu.test(exactText)) prefill.subject = "this-unit";
    const kinds = [...(/\bcharacteristics?\b/iu.test(exactText) ? ["characteristics"] : []), ...(/\brolls?\b/iu.test(exactText) ? ["rolls"] : [])];
    if (kinds.length > 0) prefill.what = kinds;
    if (/\bnegative modifiers?\b|\bworsen(?:ed|ing)?\b/iu.test(exactText)) prefill.only = "worsening";
    else if (/\bpositive modifiers?\b|\bimprov(?:ed|ing)?\b/iu.test(exactText)) prefill.only = "improving";
  }
  if (family.id === "roll-auto-result") {
    if (/\bautomatically (?:passes?|succeeds?)\b/iu.test(exactText)) prefill.outcome = "auto-pass";
    else {
      const succeeds = /\bsucceeds? only on an unmodified (\d)\+/iu.exec(exactText)?.[1];
      if (succeeds) {
        prefill.outcome = "succeeds-on";
        prefill.value = Number(succeeds);
      } else if (/\bcounts? as an? (?:unmodified )?6\b/iu.test(exactText)) prefill.outcome = "counts-as-6";
    }
  }
  if (family.id === "unit-activity") {
    const activities: Array<[RegExp, string]> = [
      [/selected to shoot/iu, "selected-to-shoot-this-phase"], [/selected to move/iu, "selected-to-move-this-phase"], [/selected to (?:shoot or )?fight|fought/iu, "fought-this-phase"],
      [/charge/iu, "charged-this-turn"], [/advance/iu, "advanced-this-turn"], [/remained stationary/iu, "remained-stationary"],
    ];
    const found = activities.flatMap(([pattern, activity]) => (pattern.test(exactText) ? [activity] : []));
    if (found.length) prefill.activities = found;
    if (/\bnot\b|\bhas not\b|\bhasn't\b/iu.test(exactText)) prefill.negated = true;
    if (/\b(?:this|your|that) (?:unit|model)\b/iu.test(exactText)) prefill.subject = "this-unit";
  }
  if (family.id === "hit-by-attacks") {
    if (/\bhit by\b/iu.test(exactText)) prefill.subject = "selected-unit";
  }
  if (family.id === "usage-limit") {
    const frequency = /once per (battle round|battle|turn|phase)/iu.exec(exactText)?.[1]?.toLowerCase();
    if (frequency) prefill.frequency = `once-per-${frequency.replace(" ", "-")}`;
    if (/your opponent's turn/iu.test(exactText)) prefill.frequency = "once-per-opponent-turn";
  }
  if (family.id === "usage-scope") {
    const per = /\bper (army|unit|model)\b/iu.exec(exactText)?.[1];
    if (per) prefill.per = per.toLowerCase();
  }
  if (family.id === "use-window") Object.assign(prefill, windowFromSource(exactText));
  if (family.id === "bearer-eligibility") {
    // "X model with the Deep Strike ability only": the ability is a requirement, not a keyword.
    const ability = /\bmodels? with the \**([A-Za-z][A-Za-z' -]*?)\** ability\b/iu.exec(exactText)?.[1];
    if (ability) prefill.abilities = [ability.trim().toLowerCase().replace(/['’]/gu, "").replace(/\s+/gu, "-")];
    const words = exactText.replace(/\bmodels? with the .*$/iu, "").replace(/\bmodel only\b.*$/iu, "").split(/,|\bor\b/u).map((item) => item.replaceAll("*", "").trim().toUpperCase()).filter((item) => /^'?[A-Z][A-Z0-9' -]*[A-Z0-9]$/u.test(item));
    if (words.length) {
      prefill.keywords = words;
      prefill.match = words.length > 1 ? "any" : "all";
    }
  }
  if (family.id === "stratagem-target" || family.id === "triggering-target") Object.assign(prefill, targetFromSource(family.id, exactText));
  if (family.id === "target-binding" && /selected as the target of/iu.test(exactText)) prefill.bound_to = "attacked-unit";
  if (family.id === "optional-use") {
    if (/\bthe bearer\b/iu.test(exactText)) prefill.who = "this-model";
    else if (/\byou can\b/iu.test(exactText)) prefill.who = "you";
    else if (/\bthis model\b/iu.test(exactText)) prefill.who = "this-model";
    else if (/\bthis unit\b/iu.test(exactText)) prefill.who = "this-unit";
  }
  if (family.id === "act-after-move") {
    const moves = [/\badvanc/iu.test(exactText) ? "advance" : null, /\bf(?:a|e)ll(?:s|ing)? back\b/iu.test(exactText) ? "fall-back" : null].filter(Boolean);
    const acts = [/\bshoot|\bshot\b/iu.test(exactText) ? "shoot" : null, /\bcharge\b/iu.test(exactText) ? "charge" : null].filter(Boolean);
    if (moves.length) prefill.moves = moves;
    if (acts.length) prefill.acts = acts;
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
    else if (/\b(?:that|this|your) unit\b/iu.test(exactText)) prefill.subject = "this-unit";
  }
  if (family.id === "regain-wounds") {
    const amount = /regains? (\d+|d3\+3|d3|d6) lost wounds?/iu.exec(exactText)?.[1];
    if (amount) prefill.amount = amount.toUpperCase();
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
  }
  const MOVE_SUBJECT_FAMILIES = new Set(["make-move", "move-through", "set-up", "battlefield-marker", "objective-sticky", "apply-mark"]);
  if (MOVE_SUBJECT_FAMILIES.has(family.id)) {
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
    else if (/\bthe selected unit\b/iu.test(exactText)) prefill.subject = "selected-unit";
    else if (/\b(?:that|this|your) unit\b/iu.test(exactText)) prefill.subject = "this-unit";
  }
  if (family.id === "make-move") {
    const verbs: Array<[RegExp, string]> = [
      [/\badvanc/iu, "advance"], [/\bfall back|falls back|falling back\b/iu, "fall-back"], [/\bcharge\b/iu, "charge"],
      [/\bpile in\b/iu, "pile-in"], [/\bconsolidat/iu, "consolidation"], [/\bsurge\b/iu, "surge"], [/\bscout\b/iu, "scout"],
      [/\bingress\b/iu, "ingress"], [/\bdisembark/iu, "disembark"], [/\bembark/iu, "embark"], [/\bpulse jet\b/iu, "pulse-jet"],
      [/\bnormal move\b/iu, "normal"],
    ];
    const kind = verbs.find(([pattern]) => pattern.test(exactText))?.[1];
    if (kind) prefill.move_type = kind;
    const distance = /\b(?:up to )?(\d*d(?:3|6)(?:\+\d+)?|\d+)"/iu.exec(exactText)?.[1];
    if (distance) prefill.distance = /^\d+$/u.test(distance) ? Number(distance) : distance.toUpperCase();
  }
  if (family.id === "set-up") {
    if (/strategic reserves/iu.test(exactText)) {
      if (/\binto strategic reserves\b/iu.test(exactText)) prefill.to = "strategic-reserves";
      else prefill.from = "strategic-reserves";
    }
    if (/\bon(?:to)? the battlefield\b/iu.test(exactText)) prefill.to = "battlefield";
    if (/\bits transport\b/iu.test(exactText)) prefill.from = "transport";
  }
  if (family.id === "resource-gain" || family.id === "resource-spend") {
    const cp = /\b(\d+)CP\b/u.exec(exactText);
    if (cp) {
      prefill.pool = "command-point";
      prefill.amount = Number(cp[1]);
    }
  }
  if (family.id === "stratagem-cost") {
    if (/\bwaive\b|without paying|\bno CP\b/iu.test(exactText)) prefill.operation = "waive";
    else if (/\breduce|less\b/iu.test(exactText)) prefill.operation = "decrease";
    else if (/\bincrease|more\b/iu.test(exactText)) prefill.operation = "increase";
    if (/\bstratagem\b/iu.test(exactText)) prefill.of = "stratagem";
    else if (/\bmanoeuvre\b/iu.test(exactText)) prefill.of = "manoeuvre";
    else if (/\bability\b/iu.test(exactText)) prefill.of = "ability";
  }
  if (family.id === "army-construction") {
    if (/\bmust be your warlord\b/iu.test(exactText)) prefill.rule = "warlord-required";
    else if (/\bcannot be your warlord\b/iu.test(exactText)) prefill.rule = "warlord-forbidden";
    else if (/\bcannot be given enhancements\b/iu.test(exactText)) prefill.rule = "enhancement-forbidden";
    else if (/\bonly one of\b/iu.test(exactText)) prefill.rule = "unique";
  }
  const PERMISSION_SUBJECT_FAMILIES = new Set(["eligibility-permission", "targeting-restriction", "counts-as", "rule-state", "damage-reduction", "return-models"]);
  if (PERMISSION_SUBJECT_FAMILIES.has(family.id)) {
    if (THIS_MODEL.test(exactText)) prefill.subject = "this-model";
    else if (bearerSubject(exactText)) prefill.subject = bearerSubject(exactText);
    else if (/\b(?:that|this|your) unit\b/iu.test(exactText)) prefill.subject = "this-unit";
  }
  if (family.id === "eligibility-permission") {
    prefill.allow = !/\bcannot\b|\bcan't\b/iu.test(exactText);
    const activities: Array<[RegExp, string]> = [
      [/\bdeclare a charge\b|\bcharge\b/iu, "declare-charge"], [/\bshoot\b/iu, "shoot"], [/\bfight\b/iu, "fight"],
      [/\bdisembark\b/iu, "disembark"], [/\bembark\b/iu, "embark"], [/\bfall back\b/iu, "fall-back"], [/\badvance\b/iu, "advance"],
      [/\bstratagem\b/iu, "use-stratagem"], [/\bissue orders?\b/iu, "issue-order"], [/\britual\b/iu, "attempt-ritual"],
      [/\benhancements?\b/iu, "use-enhancement"], [/\bobserver\b/iu, "observe"],
    ];
    const activity = activities.find(([pattern]) => pattern.test(exactText))?.[1];
    if (activity) prefill.activity = activity;
  }
  if (family.id === "targeting-restriction") {
    prefill.may = /\bmust target\b/iu.test(exactText) ? "must-target" : /\bcannot (?:be )?(?:targeted|target)\b/iu.test(exactText) ? "cannot-target" : "target";
    if (/\bstratagems?\b/iu.test(exactText)) prefill.kind = "stratagem";
    else if (/\bshoot|ranged\b/iu.test(exactText)) prefill.kind = "shoot";
    else if (/\bfight|melee\b/iu.test(exactText)) prefill.kind = "fight";
    else if (/\bcharge\b/iu.test(exactText)) prefill.kind = "charge";
    else if (/\battack/iu.test(exactText)) prefill.kind = "attack";
    if (/\benemy units?\b/iu.test(exactText)) prefill.subject = "enemy-units";
  }
  if (family.id === "rule-state") {
    prefill.direction = /\bcannot\b|\bloses?\b|\bdoes not\b/iu.test(exactText) ? "suppressed" : "granted";
  }
  if (family.id === "damage-reduction") {
    if (/\bhalve\b/iu.test(exactText)) prefill.reduction = "half";
    else if (/\bto 0\b|\bto zero\b/iu.test(exactText)) prefill.reduction = "to-zero";
    else {
      const n = /\bby (\d+)\b/iu.exec(exactText)?.[1];
      if (n) prefill.reduction = n;
    }
  }
  if (family.id === "return-models" || family.id === "destroy-models") {
    const count = /\b(\d+|d3\+3|d3\+1|d3|d6) (?:destroyed )?models?\b/iu.exec(exactText)?.[1];
    if (count) prefill.count = count.toUpperCase();
    else if (/\ball\b/iu.test(exactText)) prefill.count = "all";
  }
  if (family.id === "battle-shock-state") {
    prefill.set = !/\bno longer\b|\bis not\b/iu.test(exactText);
    prefill.recipient = /\bthe target\b|\btargets?\b/iu.test(exactText) ? "defender" : "this-unit";
  }
  for (const [name, property] of Object.entries(family.parameterSchema.properties ?? {})) {
    if (name in prefill) continue;
    if (name === "weapon_type") {
      const limited = /\b(melee|ranged) weapons?\b/iu.exec(exactText)?.[1]?.toLowerCase();
      if (limited) prefill[name] = limited;
    } else if (freeText(property)) {
      const keyword = keywordFromSource(exactText, choices(property));
      if (keyword) prefill[name] = keyword;
    } else if (numeric(property) && name === "threshold") {
      const threshold = /\b([2-6])\+/u.exec(exactText)?.[1];
      if (threshold) prefill[name] = Number(threshold);
    }
  }
  // Keep only what the family accepts, so a stray match never becomes an invalid parameter.
  const properties = family.parameterSchema.properties ?? {};
  return Object.fromEntries(Object.entries(prefill).filter(([name, value]) => {
    const property = properties[name];
    if (!property) return false;
    const options = property.type === "array" ? property.items?.enum ?? [] : choices(property);
    if (Array.isArray(value)) return options.length === 0 || value.every((item) => options.includes(String(item)));
    return typeof value !== "string" || options.length === 0 || options.includes(value) || freeText(property);
  }));
}
